insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('96f9060a-7370-599b-b872-d547316ed5a5', 'wg6-narrative-writing-p06', (select id from public.skills where slug = 'write-g6-narrative-writing'), null,
        '6-8', $q$The Lantern Handle$q$, $q$(1) I am not an actor, but I love working on the stage crew for our school plays. (2) This year we put on a play about a family crossing the prairie in a covered wagon. (3) My job was to hand each actor the right prop before they walked onstage. (4) The most important prop was a tin lantern that the main character, played by Diego, carried in the second act. (5) During the break between acts, I picked up the lantern from the prop table. (6) The handle snapped off in my hand. (7) Diego was supposed to walk on in three minutes. (8) I looked around the dark backstage area for anything that could help. (9) Then I saw the roll of silver tape our director kept for emergencies. (10) I wrapped the tape around the handle three times and squeezed it tight. (11) Silver tape can also be used to fix tents and backpacks. (12) I handed the lantern to Diego just as the lights came up.

(13) He carried it across the stage, and the handle held. (14) Nobody in the audience knew anything had gone wrong.

(15) The play was about a covered wagon.$q$, 'draft')
