-- Passage wg6-narrative-writing-p08
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('5925898f-3222-59bc-91fc-a09c9149d0af', 'wg6-narrative-writing-p08', (select id from public.skills where slug = 'write-g6-narrative-writing'), null,
        '6-8', $q$Counting Birds with Grandpa$q$, $q$(1) Every February, people around the country count the birds they see in their own yards. (2) This year, Grandpa Teodoro invited me to help him with his count. (3) We sat at his kitchen window with a notebook, a pair of binoculars, and two mugs of cocoa. (4) For the first half hour, we saw only one sparrow. (5) I started to wonder if this would be the most boring morning of my life. (6) Grandpa scattered a handful of sunflower seeds on the snowy railing. (7) Within minutes, two cardinals landed. (8) Then came three chickadees, a blue jay, and a woodpecker with a red cap. (9) I wrote down each bird as fast as I could. (10) Grandpa's house has three bedrooms and a garage.

(11) By lunchtime, we had counted twenty-two birds of nine different kinds. (12) Grandpa showed me how to send our list to the scientists who study bird populations.

(13) I counted birds.$q$, 'draft')
